const a=t=>new Intl.NumberFormat("zh-CN",{style:"currency",currency:"CNY"}).format(t/100),r=t=>new Intl.NumberFormat("zh-CN",{style:"currency",currency:"USD",minimumFractionDigits:2,maximumFractionDigits:4}).format(t),c=t=>new Intl.NumberFormat("zh-CN").format(t),m=t=>new Intl.NumberFormat("zh-CN",{notation:"compact",maximumFractionDigits:1}).format(t),s=t=>t?new Date(t).toLocaleString("zh-CN",{hour12:!1}):"暂无",i=t=>t?new Date(t).toLocaleDateString("zh-CN"):"长期有效",u={concurrency:"并发",hosted_seat:"托管席位",rental_account:"租赁账号",hosted:"托管账号",rental:"租赁账号"};function h(t,e=Date.now()){if(!t)return"等待同步";const o=Math.max(0,Math.ceil((new Date(t).getTime()-e)/6e4));if(!o)return"即将重置";const n=Math.floor(o/60);return n>=24?`${Math.floor(n/24)} 天 ${n%24} 小时`:`${n?`${n} 小时 `:""}${o%60} 分钟`}export{s as a,h as b,m as c,i as d,u as k,a as m,c as n,r as u};
